  read: { label: "lu", tone: "ok", text: "Le document lui-même a été ouvert et lu pendant le développement." },
  tested: { label: "testé", tone: "ok", text: "Méthode de calcul : ses résultats sont comparés, par des tests, à des valeurs de manuel ou à des solutions exactes." },
  page: { label: "page lue", tone: "info", text: "Seule la page de présentation (titre, objet) a été lue ; le texte de la norme ne l'a pas été." },
  excerpt: { label: "extrait", tone: "warn", text: "Vu en extrait ou par un résumé de recherche seulement : à relire avant de s'y fier." },
  typed: { label: "à vérifier", tone: "warn", text: "Valeurs ou règles reprises de la référence sans relecture consignée du document : à comparer à votre copie." },
  usual: { label: "usage", tone: "neutral", text: "Règle de pouce ou valeur typique d'usage courant, dite comme telle : l'atelier, le fournisseur ou la fiche font foi." },
