/** The groups with their lines, in the order of the screen. */
export const methodsByGroup = () => METHOD_GROUPS.map((g) => ({ ...g, methods: METHODS.filter((m) => m.group === g.id) }));
/** How many lines per level of checking : { read: n, typed: n, … } */
export function methodCounts() { const c = {}; for (const m of METHODS) c[m.how] = (c[m.how] || 0) + 1; return c; }
export const methodById = (id) => METHODS.find((m) => m.id === id) || null;
/** What is wrong in the register itself ([] when it is whole). */
export function methodProblems() {
  const out = [], seen = new Set();
  for (const m of METHODS) {
    if (seen.has(m.id)) out.push(`${m.id} : en double`); seen.add(m.id);
    if (!METHOD_GROUPS.some((g) => g.id === m.group)) out.push(`${m.id} : groupe inconnu`);
    if (!METHOD_KINDS[m.kind]) out.push(`${m.id} : nature inconnue`);
    if (!METHOD_HOW[m.how] || m.how === "none") out.push(`${m.id} : vérification non dite`);
    for (const k of ["name", "title", "covers", "uses", "check"]) if (typeof m[k] !== "string" || m[k].trim().length < 3) out.push(`${m.id} : « ${k} » manque`);
    if (m.where && !/^#\/[a-z]+/.test(m.where)) out.push(`${m.id} : lien d'outil invalide`);
    if (m.doc && !/^docs\/[A-Z_]+\.md$/.test(m.doc)) out.push(`${m.id} : document invalide`);
  }
  for (const g of METHOD_GROUPS) if (!METHODS.some((m) => m.group === g.id)) out.push(`${g.id} : groupe vide`);
  return out;
}
